def open_wms_browser(p):
    """启动 WMS 独立 browser（与 ERP 持久 profile 分开，防多账号串会话）。
    带 --start-maximized：有头模式下窗口启动即最大化，方便看快递方/偏远筛选。
    headless 下无窗口，参数无害。"""
    return p.chromium.launch(
        headless=config.HEADLESS,
        args=["--start-maximized", "--no-sandbox"],
    )

